/**
 * Create a test region and then verify that we get it from the list.
 *
 * @throws Exception
 */
@Test
void testGetRegionInfo() throws Exception {
    final String regionName = "myRegion";
    final CacheAccess<String, String> cache = JCS.getInstance(regionName);
    cache.put("key", "value");
    final JCSAdminBean admin = new JCSAdminBean();
    final List<CacheRegionInfo> regions = admin.buildCacheInfo();
    boolean foundRegion = false;
    for (final CacheRegionInfo info : regions) {
        if (info.getCacheName().equals(regionName)) {
            foundRegion = true;
            assertTrue(info.getByteCount() > 5, "Byte count should be greater than 5.");
            assertNotNull(info.getCacheStatistics(), "Should have stats.");
        }
    }
    assertTrue(foundRegion, "Should have found the region we just created.");
}

/**
 * Remove an item via the remove method.
 *
 * @throws Exception
 */
@Test
void testRemove() throws Exception {
    final JCSAdminBean admin = new JCSAdminBean();
    final String regionName = "myRegion";
    final CacheAccess<String, String> cache = JCS.getInstance(regionName);
    // clear the region
    cache.clear();
    admin.clearRegion(regionName);
    final String key = "myKey";
    cache.put(key, "value");
    final List<CacheElementInfo> elements = admin.buildElementInfo(regionName);
    assertEquals(1, elements.size(), "Wrong number of elements in the region.");
    final CacheElementInfo elementInfo = elements.get(0);
    assertEquals(key, elementInfo.getKey(), "Wrong key.");
    admin.removeItem(regionName, key);
    final List<CacheElementInfo> elements2 = admin.buildElementInfo(regionName);
    assertEquals(0, elements2.size(), "Wrong number of elements in the region after remove.");
}

/**
 * This should count the size of the array.
 *
 * @throws Exception
 */
@Test
void testByteArray() throws Exception {
    final CountingOnlyOutputStream out = new CountingOnlyOutputStream();
    final byte[] array = { 1, 2, 3, 4, 5 };
    out.write(array);
    assertEquals(array.length, out.getCount(), "Wrong number of bytes written.");
    out.close();
}

/**
 * This should count the len -- the third arg
 *
 * @throws Exception
 */
@Test
void testByteArrayLenCount() throws Exception {
    final CountingOnlyOutputStream out = new CountingOnlyOutputStream();
    final byte[] array = { 1, 2, 3, 4, 5 };
    final int len = 3;
    out.write(array, 0, len);
    assertEquals(len, out.getCount(), "Wrong number of bytes written.");
    out.close();
}

/**
 * Writes a single byte and verify the count.
 *
 * @throws Exception
 */
@Test
void testSingleByte() throws Exception {
    final CountingOnlyOutputStream out = new CountingOnlyOutputStream();
    out.write(1);
    assertEquals(1, out.getCount(), "Wrong number of bytes written.");
    out.write(1);
    assertEquals(2, out.getCount(), "Wrong number of bytes written.");
    out.close();
}

