/**
 * Test writing and reading elements that do not fit within a single block.
 *
 * @throws Exception
 */
@Test
void testWriteAndReadMultipleMultiBlockElement_setSize() throws Exception {
    // SETUP
    setUpBlockDisk("testWriteAndReadSingleBlockElement", 1024);
    // DO WORK
    final int numBlocksPerElement = 4;
    final int bytes = getBytesForBlocksOfByteArrays(disk.getBlockSizeBytes(), numBlocksPerElement);
    final int numElements = 100;
    final Random r = new Random(System.currentTimeMillis());
    final byte[] src = new byte[bytes];
    for (int i = 0; i < numElements; i++) {
        // Ensure we don't just write zeros out
        r.nextBytes(src);
        final int[] blocks = disk.write(src);
        final byte[] result = (byte[]) disk.read(blocks);
        // VERIFY
        assertEquals(src.length, result.length, "Wrong item length retured.");
        assertEquals(numBlocksPerElement, blocks.length, "Wrong number of blocks returned.");
        // We check the array contents, too, to ensure we read back what we wrote out
        for (int j = 0; j < src.length; j++) {
            assertEquals(src[j], result[j], "Mismatch at offset " + j + " in attempt # " + (i + 1));
        }
    }
    assertEquals(numBlocksPerElement * numElements, disk.getNumberOfBlocks(), "Wrong number of elements. " + disk);
}

/**
 * Adds items to cache, gets them, and removes them. The item count is more than the size of the
 * memory cache, so items should spool to disk.
 *
 * @throws Exception If an error occurs
 */
@Test
void testLargeNumberOfItems() throws Exception {
    final int items = 300000;
    final String region = "testCache1";
    System.out.println("--------------------------");
    final long initialMemory = measureMemoryUse();
    System.out.println("Before getting JCS: " + initialMemory);
    final CacheAccess<String, String> jcs = JCS.getInstance(region);
    jcs.clear();
    try {
        final ElapsedTimer timer = new ElapsedTimer();
        System.out.println("Start: " + measureMemoryUse());
        // Add items to cache
        for (int i = 0; i < items; i++) {
            jcs.put(i + ":key", region + " data " + i);
        }
        System.out.println(jcs.getStats());
        System.out.println("--------------------------");
        System.out.println("After put: " + measureMemoryUse());
        Thread.sleep(5000);
        System.out.println(jcs.getStats());
        System.out.println("--------------------------");
        System.out.println("After wait: " + measureMemoryUse());
        for (int i = 0; i < 10; i++) {
            SleepUtil.sleepAtLeast(3000);
            System.out.println("--------------------------");
            System.out.println("After sleep. " + timer.getElapsedTimeString() + " memory used = " + measureMemoryUse());
            System.out.println(jcs.getStats());
        }
        // Test that all items are in cache
        System.out.println("--------------------------");
        System.out.println("Retrieving all.");
        for (int i = 0; i < items; i++) {
            //System.out.print(  "\033[s" );
            final String value = jcs.get(i + ":key");
            if (i % 1000 == 0) {
                //System.out.print(  "\033[r" );
                System.out.println(i + " ");
            }
            assertEquals(region + " data " + i, value, "Wrong value returned.");
        }
        final long aftetGet = measureMemoryUse();
        System.out.println("After get: " + aftetGet + " diff = " + (aftetGet - initialMemory));
    } finally {
        // dump the stats to the report
        System.out.println(jcs.getStats());
        System.out.println("--------------------------");
        final long endMemory = measureMemoryUse();
        System.out.println("End: " + endMemory + " diff = " + (endMemory - initialMemory));
    }
}

