    for (int i = 0; i < count; i++) {
        final String res = jcs2.get("key:" + i);
        assertNotNull(res, "[key:" + i + "] should not be null, " + jcs2.getStats());
    }
    JCS.shutdown();
    // Re-init
    // EncryptingSerializer
    final CacheAccess<String, String> jcs3 = JCS.getInstance("blockRegion2");
    for (int i = 0; i < count; i++) {
