@Test
void testAccessExpiry() throws InterruptedException {
    final CachingProvider cachingProvider = Caching.getCachingProvider();
    final CacheManager cacheManager = cachingProvider.getCacheManager(cachingProvider.getDefaultURI(), Thread.currentThread().getContextClassLoader(), cachingProvider.getDefaultProperties());
    final Cache<Integer, Integer> cache = cacheManager.createCache("test", new MutableConfiguration<Integer, Integer>().setStoreByValue(false).setStatisticsEnabled(true).setManagementEnabled(true).setTypes(Integer.class, Integer.class).setExpiryPolicyFactory(AccessedExpiryPolicy.factoryOf(new Duration(TimeUnit.MILLISECONDS, 500))));
    try {
        cache.put(1, 2);
        cache.get(1);
        Thread.sleep(650);
        assertFalse(cache.containsKey(1));
        cache.put(1, 2);
        for (int i = 0; i < 3; i++) {
            // we update the last access to force the idle time and lastaccess to be synced
            Thread.sleep(250);
            assertTrue(cache.containsKey(1), "iteration: " + Integer.toString(i));
        }
        assertTrue(cache.containsKey(1));
        Thread.sleep(650);
        assertFalse(cache.containsKey(1));
    } finally {
        cacheManager.close();
        cachingProvider.close();
    }
}

